input.command:
node -e "
const { mergeIntervals } = require('./bench/sandbox/merge-intervals-ht.js');

// Empty
console.log('empty:', JSON.stringify(mergeIntervals([])));

// Single
console.log('single:', JSON.stringify(mergeIntervals([[1, 4]])));

// Normal merge
console.log('merge:', JSON.stringify(mergeIntervals([[1,3],[2,6],[8,10],[15,18]])));

// Touching (3 touches 3)
console.log('touch:', JSON.stringify(mergeIntervals([[1,3],[3,5]])));

// Contained
console.log('contain:', JSON.stringify(mergeIntervals([[1,10],[2,3],[4,5]])));

// Negative values
console.log('neg:', JSON.stringify(mergeIntervals([[-5,-2],[0,3],[-3,1]])));

// Unsorted input
console.log('unsorted:', JSON.stringify(mergeIntervals([[5,8],[1,3],[2,6]])));
"
